insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PS:SEM:ps-argentina-bioenergia-biocombustibles-search:bioenergia-2-y-sigue-en-biogas', 'PS', 'SEM', (select id from seo_sem.campanas where nombre = 'PS Argentina - Bioenergia / Biocombustibles - Search'), null, null, null, 'Pausar las dos — Bioenergía: ×2 y sigue en biogás', 'Pausar Bioenergía y CeSu. Si se rehace Bioenergía sobre ISCC y 2BSvs, antes definir el corte con Control Union Argentina, que acaba de abrir Biocombustible con las mismas keywords.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PS:SEM:ps-argentina-suso-agricultura-regenerativa-search:agricultura-regenerativa-y-huella-de-carbono-sin-cambios', 'PS', 'SEM', (select id from seo_sem.campanas where nombre = 'PS Argentina - SuSo - Agricultura regenerativa- Search'), null, null, null, 'Aplicar el Anexo A — Agricultura regenerativa y Huella de carbono, sin cambios', 'Sacar la amplia «agricultura regenerativa en argentina». Negativos de marcas del agro, agtech, bonos, mercado, créditos, carbono neutral. Amplias a frase. Exactas [consultoria ambiental], [iso 14064].
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PS:SEM:ps-argentina-suse-esg-reportes-search:esg-la-mas-sana-con-los-mismos-huecos', 'PS', 'SEM', (select id from seo_sem.campanas where nombre = 'PS Argentina - SuSe - ESG / Reportes - Search'), null, null, null, 'Completar negativos y exactas — ESG: la más sana, con los mismos huecos', 'gri 403, gri 401 y el patrón gri + número a negativo. [csrd], [estandar gri], [consultora esg].
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PS:SEM:argentina:el-sitio-sigue-sin-existir-en-argentina', 'PS', 'SEM', null, null, null, null, 'Páginas en español — El sitio sigue sin existir en Argentina', 'Una página en español por servicio pagado. Hasta entonces, cada campaña compite sola.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-espana-caes-search:certificados-y-sistema-cae:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU España - CAEs - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU España - CAEs - Search' and g.nombre = 'Certificados y Sistema CAE'), null, null, 'Reescribir el anuncio de Certificados y Sistema CAE', 'Siete títulos, fuerza «pobre». Ninguno dice «verificación de actuaciones» ni «sujeto obligado», que es lo que compra la campaña; el orgánico entra por «verificacion cae» y «verificador cae». La mitad del gasto viene de particulares que buscan el certificado de su vivienda: eso no se arregla con títulos sino con negativos.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-espana-ifs-search:food-safety:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU España - IFS - SEARCH'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU España - IFS - SEARCH' and g.nombre = 'Food Safety'), null, null, 'Reescribir el anuncio de Food Safety', 'Los títulos hablan de «seguridad alimentaria» en genérico y ninguno nombra IFS, ISO 22000 ni FSSC, que es lo que la gente escribe (ifs food, iso 22000, brcgs). En orgánico entran por haccp, iso 22000 y «certificaciones de seguridad alimentaria». Sugerencia: partir en tres grupos, IFS, ISO 22000/FSSC y HACCP, cada uno con su anuncio.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-espana-textile-search:gots:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU España - Textile - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU España - Textile - Search' and g.nombre = 'GOTS'), null, null, 'Reescribir el anuncio de GOTS', 'Fuerza «pobre». La descripción dice «Control Union acompaña marcas»: es vocabulario de Peterson; Control Union certifica. Lo que la gente escribe: certificado gots, sello gots, certified gots organic cotton; en orgánico, «gots en español» y «qué es gots». OEKO-TEX aparece por keyword, no por anuncio: va a negativo.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-espana-textile-search:grs:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU España - Textile - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU España - Textile - Search' and g.nombre = 'GRS'), null, null, 'Ajustar el anuncio de GRS', 'Anuncio correcto en tema; la gente escribe «global recycled standard» y «grs textile exchange», y en orgánico «grs» a secas domina (7.658 búsquedas, posición 9). Falta nombrar a Textile Exchange, que es como muchos identifican la norma.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-espana-forestal-search:pefc:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU España - Forestal - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU España - Forestal - Search' and g.nombre = 'PEFC'), null, null, 'Reescribir el anuncio de PEFC', 'Fuerza «pobre». Los términos son «pefc españa», «certificado madera pefc» y una porción creciente de «sostenibilidad» a secas por la keyword «pefc certification» en frase. FSC entra al grupo PEFC y ve un anuncio de PEFC: por eso el plan pide un grupo FSC propio, con este anuncio.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-espana-smeta-search:social:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU España - Smeta - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU España - Smeta - Search' and g.nombre = 'Social'), null, null, 'Ajustar el anuncio de Social', 'El anuncio está bien y el 80% del gasto reciente son nombres de competidores. No es un problema de anuncio: la keyword «smeta auditoria» en frase abrió la puerta. Cambio mínimo en el anuncio y negativos.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-espana-bioenergia-search:iscc:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU España - Bioenergia - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU España - Bioenergia - Search' and g.nombre = 'ISCC'), null, null, 'Ajustar el anuncio de ISCC', 'Fuerza «pobre» con relación fuerte: la gente escribe «iscc», «iscc plus», «certificado iscc» y el anuncio lo dice. El problema es que la query «iscc» casi desapareció del orgánico (605 → 11 impresiones desde España): el anuncio hoy sostiene solo el tema. Faltan títulos de ISCC EU y de la directiva RED.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-espana-plasticos-search:recyclass:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU España - Plasticos - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU España - Plasticos - Search' and g.nombre = 'RecyClass'), null, null, 'Ajustar el anuncio de RecyClass', 'Relación fuerte: «recyclass» es el 98% del gasto. El orgánico muestra tres intenciones que el anuncio no nombra: reciclabilidad, contenido reciclado y reutilización de plásticos (830 búsquedas, posición 36).
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-portugal-textile-search:gots:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Portugal - Textile - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Portugal - Textile - Search' and g.nombre = 'GOTS'), null, null, 'Ajustar el anuncio de GOTS', 'La gente escribe «gots 8.0», «gots database», «gots symbol», «norma gots». El anuncio no nombra la versión ni el símbolo. La descripción «Apoio a marcas» es vocabulario de consultoría; Control Union certifica.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-portugal-forestal-search:pefc:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Portugal - Forestal - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Portugal - Forestal - Search' and g.nombre = 'PEFC'), null, null, 'Ajustar el anuncio de PEFC', 'Relación fuerte, con «pefc o que é» entre los términos más caros: intención informativa. En orgánico, «pefc search» y «pefc certificate search»: la gente busca verificar certificados. Un título que responda «o que é» captura esa intención sin pagar por curiosidad pura.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-portugal-plasticos-search:une-15343:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Portugal - Plasticos - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Portugal - Plasticos - Search' and g.nombre = 'UNE 15343'), null, null, 'Ajustar el anuncio de UNE 15343', 'Los términos dicen «une en 15343 2008»: la gente cita la norma con año. Bien el anuncio, salvo «bso consulting» y «como reduzir a produção de resíduos», que son negativos, no títulos.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-portugal-biomasa-search:sure:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Portugal - Biomasa - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Portugal - Biomasa - Search' and g.nombre = 'SURE'), null, null, 'Ajustar el anuncio de SURE', 'Un solo término, «certificado sur», con relación fuerte. En orgánico, «sure madeira» (60 búsquedas) y «sure sustainable resources». El anuncio no nombra madera ni RED III.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-canada-forestry-search:fsc:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Canada - Forestry - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Canada - Forestry - Search' and g.nombre = 'FSC'), null, null, 'Reescribir el anuncio de FSC', 'El grupo FSC usa el mismo anuncio genérico de «Forestry Certification». La gente escribe «fsc canada», «fsc chain of custody», «how to get fsc certification» y también en francés («normes fsc», ARS 8.498). Un anuncio FSC propio, y uno en francés si se mantiene la campaña. Vale solo si se decide no pausar Forestry.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-canada-canada-gap-search:canadagap-cert:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Canada - Canada Gap - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Canada - Canada Gap - Search' and g.nombre = 'CanadaGAP cert'), null, null, 'Ajustar el anuncio de CanadaGAP cert', 'Relación fuerte en los términos correctos («canada gap», «canadagap certification», «canadagap 2026»). La descripción dice «CanadianGAP», nombre incorrecto del programa. Cargill, supply chain management e indocert son negativos, no anuncio.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-united-states-organic-usda-nop-search:switch-get-certified:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU United States - Organic - USDA NOP - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU United States - Organic - USDA NOP - Search' and g.nombre = 'Switch & Get Certified'), null, null, 'Ajustar el anuncio de Switch & Get Certified', 'Los términos más caros son definiciones («what does certified organic mean», «what is certified organic»): van a negativo, no a título. Lo que sí compra bien: «how to get certified organic», «organic certification», «national organic program». Falta nombrar el NOP y el ámbito (crop, livestock, handling).
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-canada-globalg-a-p-search:globalg-a-p-cert:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Canada - GLOBALG.A.P. - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Canada - GLOBALG.A.P. - Search' and g.nombre = 'GLOBALG.A.P cert'), null, null, 'Ajustar el anuncio de GLOBALG.A.P cert', '«global gap» sin punto es la forma en que la gente lo escribe (ARS 15.523) y ningún título lo dice así; «food safety consultant» es negativo. Títulos con «partner» y «support» suenan a consultoría.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-argentina-agroexportacion-search:eudr-proceso:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Argentina - Agroexportación - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Argentina - Agroexportación - Search' and g.nombre = 'EUDR proceso'), null, null, 'Ajustar el anuncio de EUDR proceso', 'Campaña nueva y bien armada: relación fuerte, landing propia. «eudr que significa» (ARS 5.493, un clic) es definición: negativo. Falta un título que diga qué hace Control Union en EUDR con su verbo: verificar, no asesorar.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEM:cu-argentina-biocombustible-search:iscc:anuncio', 'CU', 'SEM', (select id from seo_sem.campanas where nombre = 'CU Argentina - Biocombustible - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'CU Argentina - Biocombustible - Search' and g.nombre = 'ISCC'), null, null, 'Grupo nuevo el anuncio de ISCC', 'Las keywords dicen ISCC y el anuncio dice 2BSvs, «alternativa a ISCC EU». Cuando publique, cobrará clics de quien busca ISCC y ve otro esquema. Un grupo por esquema, cada uno con su anuncio y su landing.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PCU:SEM:pcu-espana-iso-27001-search:compra:anuncio', 'PCU', 'SEM', (select id from seo_sem.campanas where nombre = 'PCU España - ISO 27001 - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'PCU España - ISO 27001 - Search' and g.nombre = 'Compra'), null, null, 'Ajustar el anuncio de Compra', 'El anuncio ya usa las cifras y el verbo de Control Union («certificamos», «más de 100 años», «80 países», «274 oficinas»): es un anuncio de Control Union con nombre PCU. Relación fuerte. Faltan la versión 2022 y «ISO/IEC», que la gente escribe; «que dice», «dominios», «iso 27» son negativos.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PCU:SEM:pcu-argentina-iso-27001-search:compra:anuncio', 'PCU', 'SEM', (select id from seo_sem.campanas where nombre = 'PCU Argentina - ISO 27001 - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'PCU Argentina - ISO 27001 - Search' and g.nombre = 'Compra'), null, null, 'Ajustar el anuncio de Compra', 'Mismo caso. En Argentina la gente escribe «iso iec 27001», «iso 27001 2022», «norma iso 27001» y «ciberseguridad»; el anuncio no nombra la versión ni ISO/IEC. Google califica la relevancia «media» en 14 de 15 keywords: hay margen.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PS:SEM:ps-argentina-suso-agricultura-regenerativa-search:regenerativa:anuncio', 'PS', 'SEM', (select id from seo_sem.campanas where nombre = 'PS Argentina - SuSo - Agricultura regenerativa- Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'PS Argentina - SuSo - Agricultura regenerativa- Search' and g.nombre = 'Regenerativa'), null, null, 'Ajustar el anuncio de Regenerativa', 'El anuncio está bien escrito; el gasto se va en tecnología agrícola, marcas del agro y pools de siembra, que ningún título puede responder: es la amplia. El tono puede ser más de Peterson: «nosotros», acompañar, co-desarrollar.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PS:SEM:ps-argentina-suse-huella-de-carbono-gei-search:huella-carbono:anuncio', 'PS', 'SEM', (select id from seo_sem.campanas where nombre = 'PS Argentina - SuSe - Huella de carbono / GEI - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'PS Argentina - SuSe - Huella de carbono / GEI - Search' and g.nombre = 'Huella carbono'), null, null, 'Ajustar el anuncio de Huella carbono', 'Dos grupos con el mismo anuncio. La gente escribe «inventario gei argentina» (fuerte), «consultoria ambiental» y «como medir la huella de carbono de una empresa» (parcial): hay demanda de consultoría que es exactamente lo que Peterson vende y el anuncio no dice «consultora ambiental». Bonos, verra, carbono neutral son negativos.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PS:SEM:ps-argentina-suse-esg-reportes-search:reportes-esg:anuncio', 'PS', 'SEM', (select id from seo_sem.campanas where nombre = 'PS Argentina - SuSe - ESG / Reportes - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'PS Argentina - SuSe - ESG / Reportes - Search' and g.nombre = 'Reportes ESG'), null, null, 'Ajustar el anuncio de Reportes ESG', 'La campaña más sana. La gente escribe «indicadores gri», «estándares gri en español», «gri sectoriales», «csrd»: el anuncio dice «Reporte GRI» pero no «indicadores», «estándares» ni «sectoriales». En Materialidad: «matriz de materialidad», «doble materialidad».
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('PS:SEM:ps-argentina-suse-huella-de-agua-search:gestion-agua:anuncio', 'PS', 'SEM', (select id from seo_sem.campanas where nombre = 'PS Argentina - SuSe - Huella de agua - Search'), (select g.id from seo_sem.grupos g join seo_sem.campanas c on c.id = g.campana_id where c.nombre = 'PS Argentina - SuSe - Huella de agua - Search' and g.nombre = 'Gestion agua'), null, null, 'Reescribir el anuncio de Gestion agua', 'El 100% del gasto reciente es tratamiento de efluentes: no hay título que lo arregle. Si la campaña sigue, el anuncio tiene que decir qué es la huella hídrica corporativa y nombrar ISO 14046.
insert into seo_sem.recomendaciones (clave, marca, tipo, campana_id, grupo_id, sitio, pagina, titulo, detalle, evidencia, prioridad, estado, mes_alta, origen) values ('CU:SEO:espana-controlunion-com:titulo-y-snippet', 'CU', 'SEO', null, null, 'espana.controlunion.com', null, 'Título y snippet: GRS (15', 'GRS (15.968 impr., pos. 8,1, CTR 0,27%) y Welfair (11.232, pos. 8,3, 0,31%) están en primera página y nadie hace clic. Reescribir title y meta con la intención real: «Certificación GRS: requisitos, auditoría y cómo obtenerla».', '{"propiedad": "España"}'::jsonb, 'alta', 'propuesta', '2026-09', 'Recomendaciones SEO para los sitios') on conflict (clave) do update set campana_id = excluded.campana_id, grupo_id = excluded.grupo_id, sitio = excluded.sitio, pagina = excluded.pagina, titulo = excluded.titulo, detalle = excluded.detalle, evidencia = excluded.evidencia, prioridad = excluded.prioridad, origen = excluded.origen;
